import json, os, random, subprocess, sys, tempfile
random.seed(5)
book=json.load(open('/app/meterbill/data/tariffs.json'))
d=tempfile.mkdtemp()
def run(root,*a):
    p=subprocess.run([sys.executable,'-m','meterbill',*a],cwd=root,capture_output=True,text=True)
    return p.stdout,p.stderr,p.returncode
# random book
cur={"EUR":{"cash":"0.05"},"CHF":{"cash":"whole"},"USD":{"cash":"none"},"XX":{"cash":"0.5"},"YY":{"cash":"0.050"},"ZZ":{"cash":"5"}}
tar={}
for i in range(8):
    tar[f"t{i}"]={"currency":random.choice(list(cur)),"vat":random.choice(["0.21","0.055","0.125","0.005","0","-0.1"]),"standing":random.choice(["0.4110","0.0050","0.125","0.3333"]),
      "bands":[{"upto":"100","price":random.choice(["0.125","0.2","0.0333","0.145"])},{"upto":"300","price":random.choice(["0.0005","0.25","0.1"])},{"upto":None,"price":"0.1"}]}
bk=os.path.join(d,'book.json'); json.dump({"currencies":cur,"tariffs":tar},open(bk,'w'))
ad=os.path.join(d,'acc'); os.mkdir(ad)
def dec(): return random.choice(["%d.%d"%(random.randint(0,400),random.randint(0,999)),"%d.%d5"%(random.randint(0,9),random.randint(0,99)),"0.00%d"%random.randint(0,9),"0","%d"%random.randint(0,500)])
for n in range(60):
    acc={"account":f"A{n}","tariff":f"t{random.randint(0,7)}","period":{"start":"2026-03-01","end":"2026-03-%02d"%random.randint(1,31)},
     "readings":[{"meter":"m","kwh":dec()} for _ in range(random.randint(0,3))],
     "credits":[{"ref":"c","amount":random.choice([-4.25,0.125,2.675,1.005,-0.005,0.0,-0.001,1e15+0.3,random.uniform(-50,50),3])} for _ in range(random.randint(0,3))]}
    if random.random()<.5: acc["standing"]=[{"from":"2026-03-01","to":"2026-03-%02d"%random.randint(1,31),"rate":random.choice(["0.4110","-0.0050","0.0033","0","0.1250"])} for _ in range(random.randint(1,3))]
    json.dump(acc,open(os.path.join(ad,f"a{n:03}.json"),'w'))
bad=0
def cmp(*a):
    global bad
    o=run('/tmp/orig',*a); m=run('/app',*a)
    if o!=m: bad+=1; print("DIFF",a,o[0][:300],m[0][:300],o[1][-200:],m[1][-200:])
for b in (bk,None):
    pre=['--tariffs',b] if b else []
    cmp(*pre,'tariffs')
    for fmt in('text','csv'): cmp(*pre,'batch',ad,'--format',fmt)
    for f in sorted(os.listdir(ad)):
        for fmt in('text','csv','json'): cmp(*pre,'bill',os.path.join(ad,f),'--format',fmt)
    for i in range(60):
        cmp(*pre,'quote',f"t{random.randint(0,7)}" if b else random.choice(list(json.load(open('/app/meterbill/data/tariffs.json'))['tariffs'])),dec(),str(random.randint(1,60)),'--format',random.choice(['text','json']))
print("bad",bad)
EOF
python /tmp/fuzz.py

